const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');nav.querySelectorAll('a').forEach(link=>link.classList.toggle('active',link===a))}));const details={philosophy:['Spaces designed around you','A beautiful room begins with understanding how you live. Our approach brings together thoughtful layouts, natural textures and a considered palette, with every detail working towards a space that feels personal and effortless.'],residential:['Residential interiors','From a single room to an entire home, we bring together space planning, materials, lighting and furniture to create interiors that reflect your routines, your taste and the way you want to live.'],commercial:['Commercial spaces','Thoughtful workplaces and customer-facing spaces balance a clear brand identity with practical everyday needs. We consider flow, lighting, finishes and comfort as one connected experience.'],turnkey:['Turnkey solutions','A cohesive journey from the first design conversation to the finishing touches. Scope, material selections and execution are considered together so the final space feels beautifully resolved.'],styling:['Furniture & styling','The pieces you live with make a space your own. Furniture selection, textiles, lighting and finishing accents bring warmth, character and balance to an interior.'],project:['The Courtyard Home','An illustrative design concept exploring warm minimalism: natural oak, sculptural seating, rich stone and soft daylight. The palette pairs calm neutrals with burgundy accents, creating an intimate home connected to its surroundings. Imagery is a design visualization.'],contact:['Let’s talk about your space','Our direct contact details will be available here soon. In the meantime, prepare a few details for your first conversation: your location, the type and size of your space, your preferred timeline, and what you would love to change.']};const modal=document.querySelector('dialog');document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{const [title,copy]=details[b.dataset.detail];document.querySelector('#detail-title').textContent=title;document.querySelector('#detail-copy').textContent=copy;modal.showModal()}));document.querySelectorAll('.close,.dismiss').forEach(b=>b.addEventListener('click',()=>modal.close()));modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});document.querySelector('#year').textContent=new Date().getFullYear();

const consultation=document.querySelector('#consultation'),form=document.querySelector('#consultation-form'),fields=document.querySelector('#form-fields'),review=document.querySelector('#form-review'),success=document.querySelector('#form-success'),step=document.querySelector('#form-step');let consultationTrigger;
function showStage(stage){fields.hidden=stage!==1;review.hidden=stage!==2;success.hidden=stage!==3;step.textContent=stage===1?'Step 1 of 2 · Your details':stage===2?'Step 2 of 2 · Review & submit':'Preview complete';}
document.querySelectorAll('[data-consultation]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();consultationTrigger=el;showStage(1);consultation.showModal();form.elements.firstName.focus()}));
function closeConsultation(){consultation.close();form.reset();showStage(1);consultationTrigger?.focus()}
document.querySelector('.consultation-close').addEventListener('click',closeConsultation);document.querySelector('#finish-enquiry').addEventListener('click',closeConsultation);consultation.addEventListener('cancel',e=>{e.preventDefault();closeConsultation()});
form.elements.phone.addEventListener('input',()=>form.elements.phone.setCustomValidity(''));
form.addEventListener('submit',e=>{e.preventDefault();const phone=form.elements.phone,digits=phone.value.replace(/\D/g,'');phone.setCustomValidity(digits.length<7||digits.length>15?'Please enter a phone number with 7–15 digits.':'');for(const key of ['firstName','lastName']){form.elements[key].value=form.elements[key].value.trim()}if(!form.reportValidity())return;const data=new FormData(form),summary=document.querySelector('#enquiry-summary');summary.replaceChildren();for(const [label,value] of [['Name',data.get('firstName')+' '+data.get('lastName')],['Email',data.get('email')],['Phone',data.get('phone')],['Property type',data.get('property')]]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);summary.append(row)}showStage(2);document.querySelector('#edit-enquiry').focus()});
document.querySelector('#edit-enquiry').addEventListener('click',()=>{showStage(1);form.elements.firstName.focus()});document.querySelector('#submit-enquiry').addEventListener('click',()=>{showStage(3);form.reset();document.querySelector('#finish-enquiry').focus()});

(()=>{const fine=matchMedia('(hover: hover) and (pointer: fine)'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let cleanup=()=>{};
function setup(){cleanup();if(!fine.matches)return;const dot=document.createElement('span'),ring=document.createElement('span');dot.className='metro-cursor';ring.className='metro-cursor-ring';for(const el of [dot,ring]){el.setAttribute('aria-hidden','true');document.body.append(el)}let x=0,y=0,rx=0,ry=0,frame=0,lastWave=0,visible=false;const waves=new Set();
function host(){return document.querySelector('dialog[open]')||document.body}function mount(){const parent=host();if(dot.parentNode!==parent){parent.append(dot,ring);waves.forEach(w=>w.remove());waves.clear()}}
function hide(){visible=false;dot.style.opacity=ring.style.opacity='0';document.documentElement.classList.remove('metro-cursor-on');cancelAnimationFrame(frame);frame=0}
function animate(){frame=0;if(!visible)return;rx+=(x-rx)*.2;ry+=(y-ry)*.2;ring.style.left=rx+'px';ring.style.top=ry+'px';if(Math.abs(x-rx)+Math.abs(y-ry)>.1)frame=requestAnimationFrame(animate)}
function wave(){const w=document.createElement('span');w.className='metro-cursor-wave';w.setAttribute('aria-hidden','true');w.style.left=x+'px';w.style.top=y+'px';host().append(w);waves.add(w);w.addEventListener('animationend',()=>{w.remove();waves.delete(w)},{once:true})}
function move(e){if(e.pointerType==='touch')return;mount();x=e.clientX;y=e.clientY;if(!visible){rx=x;ry=y}visible=true;document.documentElement.classList.add('metro-cursor-on');dot.style.opacity=ring.style.opacity='1';dot.style.left=x+'px';dot.style.top=y+'px';const interactive=e.target.closest('a,button,input,select,textarea,summary');ring.style.width=ring.style.height=interactive?'42px':'30px';if(reduce.matches){ring.style.left=x+'px';ring.style.top=y+'px'}else{if(!frame)frame=requestAnimationFrame(animate);if(e.timeStamp-lastWave>95&&(Math.abs(e.movementX)+Math.abs(e.movementY)>2)){wave();lastWave=e.timeStamp}}}
function press(){if(visible&&!reduce.matches)wave()}function key(e){if(e.key==='Tab')hide()}
document.addEventListener('pointermove',move);document.addEventListener('pointerdown',press);document.addEventListener('keydown',key);document.documentElement.addEventListener('pointerleave',hide);window.addEventListener('blur',hide);const observer=new MutationObserver(()=>{mount();if(!document.hasFocus())hide()});observer.observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});cleanup=()=>{hide();observer.disconnect();dot.remove();ring.remove();waves.forEach(w=>w.remove());document.removeEventListener('pointermove',move);document.removeEventListener('pointerdown',press);document.removeEventListener('keydown',key);document.documentElement.removeEventListener('pointerleave',hide);window.removeEventListener('blur',hide)};}fine.addEventListener('change',setup);setup()})();
